CREATE TYPE "SourceVisibility" AS ENUM ('PLATFORM_SHARED','ORGANIZATION_PRIVATE');
CREATE TYPE "SourceLifecycleStatus" AS ENUM ('DRAFT','ACTIVE','SUSPENDED','DEPRECATED','FAILED','NEEDS_RE_REVIEW');
CREATE TYPE "ReviewDecision" AS ENUM ('APPROVED','REJECTED');
CREATE TYPE "UsagePermissionDecision" AS ENUM ('ALLOWED','DENIED');
CREATE TYPE "IngestionRunStatus" AS ENUM ('PENDING','PROCESSING','SUCCEEDED','FAILED');
CREATE TYPE "KnowledgeItemStatus" AS ENUM ('ACTIVE','SUSPENDED','DEPRECATED');

CREATE TABLE "knowledge_sources" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID,"visibility" "SourceVisibility" NOT NULL,"title" VARCHAR(200) NOT NULL,"origin" VARCHAR(120) NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "knowledge_sources_org_fk" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT,CONSTRAINT "knowledge_sources_visibility_ck" CHECK (("visibility"='PLATFORM_SHARED' AND "organization_id" IS NULL) OR ("visibility"='ORGANIZATION_PRIVATE' AND "organization_id" IS NOT NULL)));
CREATE INDEX "knowledge_sources_org_visibility_idx" ON "knowledge_sources"("organization_id","visibility");
CREATE TABLE "source_versions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_id" UUID NOT NULL REFERENCES "knowledge_sources"("id") ON DELETE RESTRICT,"version_number" INTEGER NOT NULL,"content_hash" CHAR(64) NOT NULL,"content_reference" VARCHAR(1000) NOT NULL,"content_mime_type" VARCHAR(120) NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"request_fingerprint" CHAR(64) NOT NULL,"idempotency_key" VARCHAR(255) NOT NULL,"lifecycle" "SourceLifecycleStatus" NOT NULL DEFAULT 'DRAFT',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("source_id","content_hash"),UNIQUE("source_id","idempotency_key"));
CREATE INDEX "source_versions_hash_lifecycle_idx" ON "source_versions"("content_hash","lifecycle");
CREATE TABLE "pedagogical_reviews" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_version_id" UUID NOT NULL REFERENCES "source_versions"("id") ON DELETE RESTRICT,"reviewer_user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT,"decision" "ReviewDecision" NOT NULL,"reason" VARCHAR(1000) NOT NULL,"evidence_metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "pedagogical_reviews_version_created_idx" ON "pedagogical_reviews"("source_version_id","created_at");
CREATE TABLE "usage_permissions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_version_id" UUID NOT NULL REFERENCES "source_versions"("id") ON DELETE RESTRICT,"reviewer_user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT,"decision" "UsagePermissionDecision" NOT NULL,"evidence_reference" VARCHAR(1000) NOT NULL,"scope" VARCHAR(200) NOT NULL,"valid_until" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "usage_permissions_version_created_idx" ON "usage_permissions"("source_version_id","created_at");
CREATE TABLE "source_lifecycle_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_id" UUID REFERENCES "knowledge_sources"("id") ON DELETE RESTRICT,"source_version_id" UUID REFERENCES "source_versions"("id") ON DELETE RESTRICT,"organization_id" UUID REFERENCES "organizations"("id") ON DELETE SET NULL,"actor_user_id" UUID REFERENCES "users"("id") ON DELETE SET NULL,"from_status" "SourceLifecycleStatus","to_status" "SourceLifecycleStatus" NOT NULL,"reason" VARCHAR(1000) NOT NULL,"safe_metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "source_lifecycle_version_created_idx" ON "source_lifecycle_events"("source_version_id","created_at");
CREATE TABLE "ingestion_runs" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_version_id" UUID NOT NULL REFERENCES "source_versions"("id") ON DELETE RESTRICT,"content_hash" CHAR(64) NOT NULL,"pipeline_version" VARCHAR(80) NOT NULL,"parser_version" VARCHAR(80) NOT NULL,"status" "IngestionRunStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"failure_class" VARCHAR(120),"started_at" TIMESTAMPTZ,"completed_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("content_hash","pipeline_version"));
CREATE TABLE "knowledge_items" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_version_id" UUID NOT NULL REFERENCES "source_versions"("id") ON DELETE RESTRICT,"ingestion_run_id" UUID NOT NULL REFERENCES "ingestion_runs"("id") ON DELETE RESTRICT,"organization_id" UUID,"visibility" "SourceVisibility" NOT NULL,"locator" VARCHAR(500) NOT NULL,"normalized_text" VARCHAR(30000) NOT NULL,"text_hash" CHAR(64) NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"pipeline_version" VARCHAR(80) NOT NULL,"parser_version" VARCHAR(80) NOT NULL,"status" "KnowledgeItemStatus" NOT NULL DEFAULT 'ACTIVE',"search_vector" tsvector GENERATED ALWAYS AS (to_tsvector('simple', "normalized_text")) STORED,"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("source_version_id","locator","text_hash"),CONSTRAINT "knowledge_items_visibility_ck" CHECK (("visibility"='PLATFORM_SHARED' AND "organization_id" IS NULL) OR ("visibility"='ORGANIZATION_PRIVATE' AND "organization_id" IS NOT NULL)));
CREATE INDEX "knowledge_items_search_idx" ON "knowledge_items" USING GIN("search_vector");
CREATE INDEX "knowledge_items_org_visibility_status_idx" ON "knowledge_items"("organization_id","visibility","status");
CREATE TABLE "source_version_curriculum_node_links" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"source_version_id" UUID NOT NULL REFERENCES "source_versions"("id") ON DELETE RESTRICT,"curriculum_version_id" UUID NOT NULL REFERENCES "curriculum_versions"("id") ON DELETE RESTRICT,"curriculum_node_id" UUID NOT NULL REFERENCES "curriculum_nodes"("id") ON DELETE RESTRICT,UNIQUE("source_version_id","curriculum_node_id"));
CREATE TABLE "knowledge_item_curriculum_node_links" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"knowledge_item_id" UUID NOT NULL REFERENCES "knowledge_items"("id") ON DELETE RESTRICT,"curriculum_version_id" UUID NOT NULL REFERENCES "curriculum_versions"("id") ON DELETE RESTRICT,"curriculum_node_id" UUID NOT NULL REFERENCES "curriculum_nodes"("id") ON DELETE RESTRICT,UNIQUE("knowledge_item_id","curriculum_node_id"));
CREATE INDEX "source_version_curriculum_idx" ON "source_version_curriculum_node_links"("curriculum_version_id","curriculum_node_id");
CREATE INDEX "knowledge_item_curriculum_idx" ON "knowledge_item_curriculum_node_links"("curriculum_version_id","curriculum_node_id");

CREATE OR REPLACE FUNCTION phase30_reject_source_version_identity_mutation() RETURNS trigger AS $$ BEGIN IF NEW.source_id<>OLD.source_id OR NEW.content_hash<>OLD.content_hash OR NEW.content_reference<>OLD.content_reference OR NEW.content_mime_type<>OLD.content_mime_type OR NEW.version_number<>OLD.version_number OR NEW.request_fingerprint<>OLD.request_fingerprint OR NEW.idempotency_key<>OLD.idempotency_key THEN RAISE EXCEPTION 'source version identity is immutable'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER source_version_identity_immutable BEFORE UPDATE ON source_versions FOR EACH ROW EXECUTE FUNCTION phase30_reject_source_version_identity_mutation();
CREATE OR REPLACE FUNCTION phase30_reject_knowledge_item_mutation() RETURNS trigger AS $$ BEGIN IF NEW.source_version_id<>OLD.source_version_id OR NEW.ingestion_run_id<>OLD.ingestion_run_id OR NEW.locator<>OLD.locator OR NEW.normalized_text<>OLD.normalized_text OR NEW.text_hash<>OLD.text_hash OR NEW.pipeline_version<>OLD.pipeline_version OR NEW.parser_version<>OLD.parser_version OR NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.visibility<>OLD.visibility THEN RAISE EXCEPTION 'knowledge item provenance is immutable'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER knowledge_item_provenance_immutable BEFORE UPDATE ON knowledge_items FOR EACH ROW EXECUTE FUNCTION phase30_reject_knowledge_item_mutation();
CREATE OR REPLACE FUNCTION phase30_check_curriculum_link() RETURNS trigger AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM curriculum_nodes n JOIN curriculum_versions v ON v.id=n.version_id WHERE n.id=NEW.curriculum_node_id AND n.version_id=NEW.curriculum_version_id AND v.status='PUBLISHED') THEN RAISE EXCEPTION 'curriculum link must reference an exact published version and node'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER source_version_curriculum_exact BEFORE INSERT OR UPDATE ON source_version_curriculum_node_links FOR EACH ROW EXECUTE FUNCTION phase30_check_curriculum_link();
CREATE TRIGGER knowledge_item_curriculum_exact BEFORE INSERT OR UPDATE ON knowledge_item_curriculum_node_links FOR EACH ROW EXECUTE FUNCTION phase30_check_curriculum_link();
CREATE OR REPLACE FUNCTION phase30_audit_content_guard() RETURNS trigger AS $$ BEGIN IF NEW.metadata::text ~* '(normalized_text|fixtureContent|source_text|student)' THEN RAISE EXCEPTION 'unsafe audit metadata'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_events_phase30_content_guard BEFORE INSERT ON audit_events FOR EACH ROW EXECUTE FUNCTION phase30_audit_content_guard();
